package jp.personal.hanshinedge.prospective;
import android.content.Context;import android.os.SystemClock;import androidx.annotation.NonNull;import androidx.work.*;import org.json.*;
public class RuntimeWorker extends Worker {
 public interface Runner {void run(Context c,ProspectiveRuntime r,String id,String stage)throws Exception;}
 private final Runner runner;
 public RuntimeWorker(@NonNull Context c,@NonNull WorkerParameters p){this(c,p,RuntimeWorker::networkTask);}
 public RuntimeWorker(Context c,WorkerParameters p,Runner testRunner){super(c,p);runner=testRunner;}
 private static void networkTask(Context c,ProspectiveRuntime r,String id,String stage)throws Exception{JSONObject reg=r.registration(id);if(reg==null)throw new IllegalStateException("NOT_PROSPECTIVE");if(stage.equals("RESULT")){if(r.find("RESULT","RESULT:"+id)==null){JSONObject[] proof={null};JSONObject result=JraSource.outcome(c,reg,proof);r.result(id,result,proof[0]);}settleExisting(r,id);return;}if(r.find("TIMECHAIN","TC:"+id+":"+stage)!=null)return;JSONObject[] proof={null};JSONObject latest=JraSource.latest(c,reg,proof);long decisionAt=System.currentTimeMillis();r.capture(id,stage,latest,proof[0],decisionAt,SystemClock.elapsedRealtime());if("T-5".equals(stage))r.shadowDecision(id,latest,decisionAt);else r.shadow(id);}
 public static void settleExisting(ProspectiveRuntime r,String id)throws Exception{JSONObject row=r.find("RESULT","RESULT:"+id);if(row==null)return;JSONObject outcome=new JSONObject(row.getString("payload")),reg=r.registration(id);JSONArray buys=r.rows("FORMAL_BUY");for(int i=0;i<buys.length();i++){JSONObject b=buys.getJSONObject(i),p=new JSONObject(b.getString("payload"));if(!id.equals(p.optString("race_id")))continue;String ticket=b.getString("key").substring(("BUY:"+id+":").length());if(r.find("SETTLEMENT","SETTLEMENT:"+id+":"+ticket)!=null)continue;if(!p.has("horse_no")||!p.has("stake_yen"))throw new IllegalStateException("EXISTING_BUY_SELECTION_OR_STAKE_UNAVAILABLE");long stake=p.getLong("stake_yen");if(stake<0||stake!=p.getDouble("stake_yen"))throw new IllegalStateException("STAKE_INVALID");long payoutPer100=0;JSONArray wins=outcome.getJSONArray("win_payout");for(int j=0;j<wins.length();j++)if(wins.getJSONObject(j).getInt("horse_no")==p.getInt("horse_no"))payoutPer100=wins.getJSONObject(j).getLong("payout_per_100");JSONObject settlement=new JSONObject().put("race_id",id).put("data_status","SETTLEMENT").put("realMoney","BLOCKED").put("payout_yen",Math.multiplyExact(stake,payoutPer100)/100).put("result_source",outcome.getString("result_source")).put("result_raw_sha256",outcome.getString("result_raw_sha256"));r.runtime.settleOnce(r.context(reg.getJSONObject("race"),true,true),ticket,settlement.toString(),r.runtime.settlementStatus().getString("head"));}}
 @NonNull @Override public Result doWork(){String prefix=getInputData().getString("prefix"),id=getInputData().getString("race_id"),stage=getInputData().getString("stage");if(prefix==null)prefix="jra-ui";try(ProspectiveRuntime r=new ProspectiveRuntime(getApplicationContext(),prefix)){if(stage==null||id==null)throw new IllegalArgumentException("WORK_INPUT_REQUIRED");if(stage.equals("RESULT")||r.find("TIMECHAIN","TC:"+id+":"+stage)==null)runner.run(getApplicationContext(),r,id,stage);BackgroundScheduler.recordRun(getApplicationContext(),prefix,null);return Result.success();}catch(Exception e){BackgroundScheduler.recordRun(getApplicationContext(),prefix,e.getMessage());int max="RESULT".equals(stage)?6:3;if(getRunAttemptCount()+1<max)return Result.retry();if(stage!=null&&!stage.equals("RESULT")){try(ProspectiveRuntime r=new ProspectiveRuntime(getApplicationContext(),prefix)){r.unavailable(id,stage,e.getMessage(),System.currentTimeMillis());}catch(Exception ignored){}}return Result.failure();}}
}
